const gatewayGetSpanDetail = `-- name: GatewayGetSpanDetail :one
WITH span_row AS (
  SELECT
    id,
    agent_name,
    session_id,
    trace_id,
    span_id,
    parent_span_id,
    start_time,
    end_time,
    duration_ns,
    name,
    span_class,
    operation_name,
    kind,
    status_code,
    error_type,
    error_message,
    model,
    tool_name,
    input_tokens,
    output_tokens,
    cached_input_tokens,
    cached_write_tokens,
    cost_usd,
    llm_finish_reason,
    resource_attributes,
    span_attributes,
    ingested_at
  FROM observer_trace_spans sp
  WHERE sp.tenant_namespace = $1
    AND sp.agent_name = $2
    AND sp.trace_id = $3
    AND sp.span_id = $4
  ORDER BY sp.start_time ASC, sp.id ASC
  LIMIT 1
)
SELECT
  s.id,
  s.agent_name,
  s.session_id,
  s.trace_id,
  s.span_id,
  s.parent_span_id,
  s.start_time,
  s.end_time,
  s.duration_ns,
  s.name,
  s.span_class,
  s.operation_name,
  s.kind,
  s.status_code,
  s.error_type,
  s.error_message,
  s.model,
  s.tool_name,
  s.input_tokens,
  s.output_tokens,
  s.cached_input_tokens,
  s.cached_write_tokens,
  s.cost_usd,
  s.llm_finish_reason,
  s.resource_attributes,
  s.span_attributes,
  s.ingested_at,
  COALESCE(p.input_messages, 'null'::jsonb) AS input_messages,
  COALESCE(p.output_messages, 'null'::jsonb) AS output_messages,
  COALESCE(p.tool_arguments, 'null'::jsonb) AS tool_arguments,
  COALESCE(p.tool_result, 'null'::jsonb) AS tool_result
FROM span_row s
LEFT JOIN observer_trace_span_payloads p
  ON p.trace_id = s.trace_id
  AND p.span_id = s.span_id
  AND p.start_time = s.start_time
`

